const apiData = $input.first().json;
const domainItem = $('Split Into Individual Domains').first().json;

const domain = domainItem.domain;
const owner = domainItem.owner || domain;
const daysRemaining = apiData.days_remaining ?? null;
const validTo = apiData.valid_till ?? null;
const validFrom = apiData.valid_from ?? null;
const issuer = apiData.issuer ?? 'Unknown';
const subject = apiData.host ?? domain;
const isValid = apiData.valid ?? false;

let status = 'VALID';
let severity = 'info';

if (!isValid || daysRemaining === null) {
  status = 'ERROR'; severity = 'critical';
} else if (daysRemaining < 0) {
  status = 'EXPIRED'; severity = 'critical';
} else if (daysRemaining <= 7) {
  status = 'CRITICAL'; severity = 'critical';
} else if (daysRemaining <= 30) {
  status = 'WARNING'; severity = 'warning';
}

return [{ json: { domain, owner, status, severity, daysRemaining, validFrom, validTo, issuer, subject, checkedAt: new Date().toISOString().split('T')[0] } }];

const allItems = $input.all();
const results = allItems.map(i => i.json);

const critical = results.filter(r => r.severity === 'critical');
const warning  = results.filter(r => r.severity === 'warning');
const valid    = results.filter(r => r.severity === 'info');
const hasIssues = critical.length > 0 || warning.length > 0;

let summaryForMistral = 'SSL Certificate Daily Scan Results\nDate: ' + new Date().toISOString().split('T')[0] + '\nTotal domains checked: ' + results.length + '\n\n';

if (critical.length > 0) {
  summaryForMistral += 'CRITICAL / EXPIRED / ERROR (' + critical.length + '):\n';
  critical.forEach(r => {
    summaryForMistral += '  - ' + r.domain + ' (Owner: ' + r.owner + ')\n';
    summaryForMistral += '    Status: ' + r.status + ' | Days remaining: ' + (r.daysRemaining !== null ? r.daysRemaining : 'N/A') + '\n';
    if (r.validTo) summaryForMistral += '    Expires: ' + r.validTo + ' | Issuer: ' + r.issuer + '\n';
  });
  summaryForMistral += '\n';
}

if (warning.length > 0) {
  summaryForMistral += 'WARNING — Expiring Soon (' + warning.length + '):\n';
  warning.forEach(r => {
    summaryForMistral += '  - ' + r.domain + ' (Owner: ' + r.owner + ')\n';
    summaryForMistral += '    Days remaining: ' + r.daysRemaining + ' | Expires: ' + r.validTo + ' | Issuer: ' + r.issuer + '\n';
  });
  summaryForMistral += '\n';
}

if (valid.length > 0) {
  summaryForMistral += 'VALID (' + valid.length + '):\n';
  valid.forEach(r => {
    summaryForMistral += '  - ' + r.domain + ': ' + r.daysRemaining + ' days remaining (expires ' + r.validTo + ')\n';
  });
}

let subjectPrefix = '✅';
if (critical.length > 0) subjectPrefix = '🔴';
else if (warning.length > 0) subjectPrefix = '🟡';

const emailSubject = subjectPrefix + ' SSL Daily Report [' + new Date().toISOString().split('T')[0] + '] — ' + critical.length + ' Critical, ' + warning.length + ' Warning, ' + valid.length + ' Valid';

return [{ json: { hasIssues, critical: critical.length, warning: warning.length, valid: valid.length, total: results.length, summaryForMistral, emailSubject, checkedAt: new Date().toISOString().split('T')[0] } }];

// Build the Mistral request body as a clean JSON string
// This avoids the 'JSON parameter needs to be valid JSON' error
const summary = $input.first().json.summaryForMistral;

const body = {
  model: 'mistral-small-latest',
  temperature: 0.2,
  max_tokens: 900,
  messages: [
    {
      role: 'system',
      content: 'You are a cybersecurity expert specializing in SSL/TLS certificate management. You write clear professional daily security reports for mixed audiences — technical teams and management. Be concise, structured, and always include prioritized remediation steps with realistic deadlines.'
    },
    {
      role: 'user',
      content: 'Write a professional daily SSL certificate security report email based on this scan data:\n\n' + summary + '\n\nStructure:\n1. Executive Summary — 2-3 sentences on overall SSL health\n2. Immediate Action Required — critical and expired certs, specific steps per domain\n3. Action Needed Soon — warning certs, deadline recommendations\n4. SSL Hygiene Recommendations\n\nTone: professional, direct, suitable for both IT and management. Plain text only, no markdown.'
    }
  ]
};

return [{ json: { body: JSON.stringify(body), emailSubject: $input.first().json.emailSubject, checkedAt: $input.first().json.checkedAt, total: $input.first().json.total } }];

const tls = require('tls');

const item = $input.first().json;
const domain = (item.domain || '').replace(/^https?:\/\//, '').split('/')[0].trim();
const owner = item.owner || domain;

if (!domain) throw new Error('No domain provided');

const result = await new Promise((resolve) => {

  const socket = tls.connect({
    host: domain,
    port: 443,
    servername: domain,
    rejectUnauthorized: false,
    timeout: 10000
  }, () => {
    try {
      const cert = socket.getPeerCertificate(true);
      socket.end();

      if (!cert || Object.keys(cert).length === 0) {
        resolve({
          domain, owner, status: 'ERROR', severity: 'critical',
          daysRemaining: null, validFrom: null, validTo: null,
          issuer: 'N/A', issuedTo: domain,
          serialNumber: 'N/A', fingerprint: 'N/A',
          checkedAt: new Date().toISOString().split('T')[0],
          error: 'No certificate returned by server'
        });
        return;
      }

      const now           = new Date();
      const validTo       = new Date(cert.valid_to);
      const validFrom     = new Date(cert.valid_from);
      const daysRemaining = Math.floor((validTo - now) / (1000 * 60 * 60 * 24));

      // ─── Thresholds ────────────────────────────────────────────────
      // 30+ days  → OK
      // 14 days   → WARNING
      //  7 days   → CRITICAL
      //  expired  → EXPIRED
      let status = 'OK', severity = 'info';
      if      (daysRemaining < 0)   { status = 'EXPIRED';  severity = 'critical'; }
      else if (daysRemaining <= 7)  { status = 'CRITICAL'; severity = 'critical'; }
      else if (daysRemaining <= 14) { status = 'WARNING';  severity = 'warning';  }
      // else: 15-29 days falls through to OK as well — adjust if needed

      const issuerObj = cert.issuer || {};
      const issuer    = issuerObj.O || issuerObj.CN || 'Unknown';
      const issuedTo  = (cert.subject || {}).CN || domain;

      resolve({
        domain, owner, status, severity, daysRemaining,
        validFrom: validFrom.toISOString().split('T')[0],
        validTo:   validTo.toISOString().split('T')[0],
        issuer, issuedTo,
        serialNumber: cert.serialNumber || 'N/A',
        fingerprint:  cert.fingerprint  || 'N/A',
        checkedAt: new Date().toISOString().split('T')[0],
        error: null
      });

    } catch (err) {
      socket.end();
      resolve({
        domain, owner, status: 'ERROR', severity: 'critical',
        daysRemaining: null, validFrom: null, validTo: null,
        issuer: 'N/A', issuedTo: domain,
        serialNumber: 'N/A', fingerprint: 'N/A',
        checkedAt: new Date().toISOString().split('T')[0],
        error: err.message
      });
    }
  });

  socket.on('error', (err) => resolve({
    domain, owner, status: 'ERROR', severity: 'critical',
    daysRemaining: null, validFrom: null, validTo: null,
    issuer: 'N/A', issuedTo: domain,
    serialNumber: 'N/A', fingerprint: 'N/A',
    checkedAt: new Date().toISOString().split('T')[0],
    error: err.message
  }));

  socket.setTimeout(10000, () => {
    socket.destroy();
    resolve({
      domain, owner, status: 'TIMEOUT', severity: 'critical',
      daysRemaining: null, validFrom: null, validTo: null,
      issuer: 'N/A', issuedTo: domain,
      serialNumber: 'N/A', fingerprint: 'N/A',
      checkedAt: new Date().toISOString().split('T')[0],
      error: 'Connection timed out after 10 seconds'
    });
  });

});

return [{ json: result }];
